#include <stdlib.h>

static int N, K;
static int *startArr, *adjList;
static int *par, *order, *stk;
static int *needA, *covA;

/* Greedy check: can K radars of radius R protect the whole tree? */
static int check(int R) {
    int cnt = 0;
    for (int i = N - 1; i >= 0; i--) {
        int u = order[i];
        int need = -1, cov = -1;
        int p = par[u];
        int e = startArr[u + 1];
        for (int j = startArr[u]; j < e; j++) {
            int c = adjList[j];
            if (c == p) continue;
            int nc = needA[c];
            if (nc >= 0) { nc++; if (nc > need) need = nc; }
            int cc = covA[c];
            if (cc >= 0) { cc--; if (cc > cov) cov = cc; }
        }
        if (need < 0) {
            if (cov < 0) need = 0;        /* u itself uncovered */
        } else if (cov >= need) {
            need = -1;                     /* existing radar covers all uncovered */
        }
        if (need >= R) {                   /* forced: place radar at u */
            if (++cnt > K) return 0;
            cov = R;
            need = -1;
        }
        needA[u] = need;
        covA[u] = cov;
    }
    if (needA[order[0]] >= 0) cnt++;       /* one more radar at the root */
    return cnt <= K;
}

